    public static int paTextTo(emon.Port.Cells txt, emon.Port.Cells ar, int h, emon.Port.Cells out, int at) {
        // Keep the text of the resolved string or name `h` as a run at out[at, at+2);
        // absent (-1 0) when h is neither.
        int s = 0;
        int n = 0;
        if (h == 0) {
            emon.Port.cellsSet(out, at, -1);
            emon.Port.cellsSet(out, at + 1, 0);
            return 0;
        }
        if ((Pdflex.plKindOf(ar, h) != 5) && (Pdflex.plKindOf(ar, h) != 4)) {
            emon.Port.cellsSet(out, at, -1);
            emon.Port.cellsSet(out, at + 1, 0);
            return 0;
        }
        s = emon.Port.cellsLen(txt);
        n = Pdfx.pxTextPush(ar, h, txt);
        emon.Port.cellsSet(out, at, s);
        emon.Port.cellsSet(out, at + 1, n);
        return n;
    }
